WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_st_ratio'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '按比例分段', 'kp-eng-st-ratio', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "按比例分段"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不是按时间切分，而是按“工程量进度条”切分。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "特征：“完成了一半后，效率提高……” 或 “完成了总工程量的 1/3 时……”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "既然明确按比例切分，在赋总量 W 时，一定要赋一个【能够被该比例整除】的数字！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题目找到分段比例(如1/3, 1/2)] --> B[寻找所有单独时间的公倍数]\nB --> C[将公倍数扩大, 确保它能被比例的分母整除, 作为 W]\nC --> D[将 W 直接切成两块具体的数值 W1 和 W2]\nD --> E[分别用 W1 / P1 和 W2 / P2 求出前后两段时间]\nE --> F[相加得出总时间]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲独做需 10 天，乙独做需 15 天。两人合作，当完成总工程量的 1/4 时，甲被调走。剩下由乙完成，共需几天？选项：A. 11  B. 12  C. 12.5  D. 13"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "特赋 W：10和15公倍数是30。题目有“1/4”，为了好算，把 W 设为 30 的 2 倍，即 W = 60！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出效率：P甲 = 6，P乙 = 4。P合 = 10。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "切分工程量：完成 1/4，即 60 × 1/4 = 15。剩下的 3/4 为 45。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算时间1：前 15 是合作的，耗时 15 ÷ P合(10) = 1.5 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算时间2：后 45 是乙单干的，耗时 45 ÷ P乙(4) = 11.25 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "汇总：总需 1.5 + 11.25 = 12.75 天。（注：选项只是示意，掌握切 W 的思想最重要）"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "带着分数硬算：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果按初中方法，列出 1/4 ÷ (1/10 + 1/15)，你会发现在高压的考场上，这种繁分数的化简极容易出错。通过放大 W 消灭所有分数，是公考的终极智慧。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "强化 W 的“定制化”能力。只要题干里出现了分数，W 就必须包含这个分数的分母作为因子。"}]}]}$$ AS jsonb), NULL, '按比例分段的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "按比例分段"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_st_ratio", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
